"""Cart pricing helpers.

Each function independently calls the builtin `round(x, 2)`, which uses
banker's rounding on the underlying float representation and produces
inconsistent cent-boundary results (e.g. some `.005` cases round down).
"""

from __future__ import annotations


def line_item_total(unit_price: float, quantity: int) -> float:
    """unit_price * quantity, rounded to the nearest cent."""
    return round(unit_price * quantity, 2)


def apply_tax(subtotal: float, tax_rate: float) -> float:
    """subtotal * (1 + tax_rate), rounded to the nearest cent."""
    return round(subtotal * (1 + tax_rate), 2)


def compute_invoice_total(line_totals: list, tax_rate: float) -> float:
    """Sum of line_totals, then apply_tax, rounded to the nearest cent."""
    subtotal = round(sum(line_totals), 2)
    return round(apply_tax(subtotal, tax_rate), 2)
```

